/* eslint-disable react/prop-types */
import { InputLabel, TextField } from "@mui/material";

const InputField = ({
  text,
  label = "",
  value,
  onChange,
  onKeyDown,
  sx,
  defaultValue,
  inputProps,
  InputProps,
  error,
  helperText,
  required,
  disabled,
  type
}) => {
  // const inputValue = value !== undefined ? value : defaultValue
  return (
    <>
      <InputLabel sx={{color: '#2B3343'}} id={`${text}-label`}>{label}</InputLabel>
      <TextField
        sx={sx}
        name={text}
        value={value}
        onChange={onChange}
        onKeyDown={onKeyDown}
        defaultValue={defaultValue}
        inputProps={inputProps}
        InputProps={InputProps}
        error={!!error}
        helperText={helperText}
        required={required}
        disabled={disabled}
        type={type}
      />
    </>
  )
}
export default InputField