/* eslint-disable no-unused-vars */
import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography,} from '@mui/material';
import InputLabel from '@mui/material/InputLabel';
import { axios } from '../../utils/axios';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import GoBackButton from '../../components/goBackButton/GoBackButton';
import InputField from '../../components/input/inputField';
import useResponsive from '../../hooks/useResponsive';

export default function AddaminPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const [iconname, setIconName] = useState('');
  const [iconlabel, setIconLabel] = useState('');
  const [imageFile, setImageFile] = useState(null);
  const [imagepreview, setImagepreview] = useState(null);
  const [iconNameError, setIconNameError] = useState('');
  const [iconError, setIconError] = useState('');
  const { i18 } = useMyContext();
  const queryParams = new URLSearchParams(location.search);
  const id = queryParams.get("id")
  const process = "Add";
  const types = "Icon";
  const isMobile = useResponsive('down', 'sm')

  const isAddButtonDisabled = !iconname || !iconlabel || !imageFile;

  const backtouser = () => {
    navigate('/dashboard/icon');
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();

    reader.onloadend = () => {
      setImagepreview(reader.result);
      setImageFile(file);
    };

    if (file) {
      reader.readAsDataURL(file);
    }
  };
  const Addicon = async () => {
    try {
      const formData = new FormData();
      formData.append('name', iconname);
      formData.append('label', iconlabel);
      formData.append('icon', imageFile);

      const res = await axios.post(`module/admin/icon/${id}`, formData);

      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success');
        navigate('/dashboard/icon');
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };
  const handleIconNameChange = (e) => {
    const inputValue = e.target.value;
    setIconName(inputValue);

    // Regular expression to match only letters
    const lettersOnlyRegex = /^[A-Za-z]+$/;

    if (!lettersOnlyRegex.test(inputValue)) {
      setIconNameError('invalid');
    } else {
      setIconNameError('');
    }
  };
  const handleIconLabelChange = (e) => {
    const inputValue = e.target.value;
    setIconLabel(inputValue);

    // Regular expression to match only letters
    const lettersOnlyRegex = /^[A-Za-z]+$/;

    if (!lettersOnlyRegex.test(inputValue)) {
      setIconError('invalid');
    } else {
      setIconError('');
    }
  };
  return (
    <>
      <Helmet>
        <title>{process} Icon</title>
      </Helmet>
      <Card sx={{ padding: '20px 10px', margin: '30px 0px' }}>
        <Grid container sx={{ borderBottom: '1px solid #dbe0e4', padding: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
              {/* {process} {types} */}
              {i18?.LISTINGPAGE?.ADD_ICON || "Add Icon"}
            </Typography>
            <GoBackButton
              label={i18?.LISTINGPAGE?.GO_BACK || "Go Back"}
              onClick= {backtouser}
              icon="icon-park-twotone:back"
            />
          </Grid>
        </Grid>

        <Grid container sx={{ marginTop: '10px' }}>
          <Grid item xs={12} sm={6} sx={{ padding: '0px 5px' }}>
            <InputField
              value={iconname}
              name="name"
              label={i18?.LISTINGPAGE?.NAME || "Name"}
              sx={{ margin: '10px 0px', width: '100%' }}
              onChange={handleIconNameChange}
            />
          </Grid>
          <Grid item xs={12} sm={6} sx={{ padding: '0px 5px' }}>
            <InputField
              value={iconlabel}
              name="label"
              label={i18?.LISTINGPAGE?.LABEL || "Label"}
              sx={{ margin: '10px 0px', width: '100%' }}
              onChange={handleIconLabelChange}
            />
          </Grid>
        </Grid>

        <Grid container justifyContent="flex-start" alignItems="center" sx={{ marginTop: '10px', padding: '0px 5px' }}>
          <InputLabel
            id="demo-simple-select-label"
            sx={{
              cursor: 'pointer',
              border: '1px solid #adb5bd',
              borderRadius: '5px',
              padding: '15px',
              width: isMobile ? '100%' : '50%',
            }}
          >
            <input type="file" id="image-upload" style={{ display: 'none' }} onChange={(e) => handleImageChange(e)} />
            <span style={{ color: 'black' }}>{i18?.LISTINGPAGE?.UPLOAD_ICON || "Upload Icon"}</span>
            {imagepreview && (
              <img
                src={imagepreview}
                alt="Preview"
                style={{ maxWidth: '50px', width: '100%', marginTop: '8px' }}
              />
            )}
          </InputLabel>
        </Grid>

        <Grid container justifyContent="flex-end" sx={{ marginTop: '10px', padding: '0px 5px' }}>
          <Button variant="contained" disabled={isAddButtonDisabled} onClick={() => Addicon()}>
            {i18?.LISTINGPAGE?.ADD || "Add"}
          </Button>
        </Grid>
      </Card>

    </>
  );
}
